FUNCTION_BLOCK FB
(* ENGINEERING_CONTRACT
   flowSP [t/h]: active only in normal cascade PI; held on mode change to 2; manual on first/reset/fault/manual-normal/auto-normal.
   valveCommand [%]: active in normal auto/cascade inner PI; held on mode change to 0/1; manual on first/reset/fault/manual-normal.
   fault: combinational from mode and scanSeconds; not latched. PUB010/N10-S10.
   normalMode: TRUE iff has_prev AND mode unchanged AND no fault AND no reset rising edge. PUB? N10-S11.
   accT/accF: retained integrators, back-calculated from final outputs and current errors every scan for anti-windup/bumpless transfer.
   Priority: first execution, reset rising, fault, mode change, normal operation; reset overrides fault for outputs/integrators, fault is still reported. PUB007.
   Units/bounds: flowSP 0..50 t/h, valveCommand 0..100 %, scanSeconds seconds, KpT=1.0, KiT=0.2, KpF=2.0, KiF=0.5.
*)
(* CONTRACT_RULES [] *)
VAR_INPUT
    mode : INT;
    resetBtn : BOOL;
    scanSeconds : REAL;
    tempSP : REAL;
    tempPV : REAL;
    flowPV : REAL;
    manualFlowSP : REAL;
    manualValve : REAL;
END_VAR
VAR_OUTPUT
    flowSP : REAL;
    valveCommand : REAL;
    fault : BOOL;
    normalMode : BOOL;
END_VAR
VAR
    tmp_hasPrev : BOOL := FALSE;
    tmp_prevMode : INT := 0;
    tmp_prevFlowSP : REAL := 0.0;
    tmp_prevValve : REAL := 0.0;
    tmp_accT : REAL := 0.0;
    tmp_accF : REAL := 0.0;
    tmp_resetTrigger : R_TRIG;
    tmp_fault : BOOL;
    tmp_resetRise : BOOL;
    tmp_eT : REAL;
    tmp_eF : REAL;
    tmp_trial : REAL;
    tmp_valveRaw : REAL;
    tmp_flowRaw : REAL;
END_VAR

tmp_resetTrigger(CLK := resetBtn);
tmp_resetRise := tmp_resetTrigger.Q;

tmp_fault := (mode < 0) OR (mode > 2) OR (scanSeconds <= 0.0) OR (scanSeconds > 10.0);
fault := tmp_fault;

IF NOT tmp_hasPrev THEN
    normalMode := FALSE
